    68	    private void createReservation(Context ctx) {
    69	        Map<String, Object> body = readBody(ctx);
    70	        Reservation r = service.create(
    71	                integer(body, "roomNumber"),
    72	                text(body, "guestName"),
    73	                text(body, "guestEmail"),
    74	                identityTypes.parse(body),
    75	                date(text(body, "checkIn")),
    76	                date(text(body, "checkOut")),
