    82	    private Map<String, Object> readBody(Context ctx) {
    83	        try {
    84	            JsonNode node = MAPPER.readTree(ctx.body());
    85	            if (node == null || !node.isObject()) throw AppException.invalid("O corpo precisa ser um objeto JSON.");
    86	            Map<String, Object> body = new LinkedHashMap<>();
    87	            node.fields().forEachRemaining(e -> {
    88	                JsonNode v = e.getValue();
    89	                if (v.isTextual()) body.put(e.getKey(), v.asText());
    90	                else if (v.isIntegralNumber()) body.put(e.getKey(), v.asInt());
    91	                else if (!v.isNull()) body.put(e.getKey(), v.toString());
    92	            });
    93	            return body;
    94	        } catch (JsonProcessingException e) {
    95	            throw AppException.invalid("O corpo não é um JSON válido.");
    96	        }
    97	    }
