    99	    private static String text(Map<String, Object> body, String field) {
   100	        if (!(body.get(field) instanceof String s) || s.isBlank()) {
   101	            throw AppException.invalid("Campo obrigatório ausente ou inválido: " + field);
   102	        }
   103	        return s.trim();
   104	    }
   105	
   106	    private static int integer(Map<String, Object> body, String field) {
   107	        if (!(body.get(field) instanceof Integer i)) {
   108	            throw AppException.invalid("Campo obrigatório ausente ou inválido: " + field);
   109	        }
   110	        return i;
   111	    }
