   145	
   146	    private static void json(Context ctx, int status, Object body) {
   147	        try {
   148	            ctx.status(status).contentType("application/json").result(MAPPER.writeValueAsString(body));
   149	        } catch (JsonProcessingException e) {
   150	            throw new IllegalStateException(e);
   151	        }
   152	    }
