     1	package br.com.marealta;
     2	
     3	import java.time.LocalDate;
     4	import java.util.function.Consumer;
     5	
     6	public class ReservationService {
     7	    private final RoomCatalog rooms;
     8	    private final PriceCalculator prices;
     9	    private final ReservationRepository reservations;
    10	    private final MessageRepository messages;
    11	
    12	    public ReservationService(RoomCatalog rooms, PriceCalculator prices, ReservationRepository reservations,
    13	                              MessageRepository messages) {
    14	        this.rooms = rooms;
    15	        this.prices = prices;
    16	        this.reservations = reservations;
    17	        this.messages = messages;
    18	    }
    19	
    20	    public synchronized Reservation create(int roomNumber, String guestName, String guestEmail,
    21	                                           GuestIdentity identity, LocalDate checkIn, LocalDate checkOut,
    22	                                           int guests, RatePlan plan) {
    23	        if (guests < 1) throw AppException.invalid("É preciso pelo menos um hóspede.");
    24	        if (!checkOut.isAfter(checkIn)) throw AppException.invalid("A saída precisa ser depois da entrada.");
    25	        Room room = rooms.find(roomNumber)
    26	                .orElseThrow(() -> new AppException(404, "ROOM_NOT_FOUND", "Quarto " + roomNumber + " não existe."));
    27	        if (guests > room.type().capacity()) {
    28	            throw new AppException(422, "CAPACITY_EXCEEDED",
    29	                    "O quarto " + roomNumber + " comporta até " + room.type().capacity() + " pessoas.");
    30	        }
    31	        boolean taken = reservations.findAll().stream()
    32	                .filter(r -> r.status() != ReservationStatus.CANCELLED)
    33	                .filter(r -> r.room().number() == roomNumber)
    34	                .anyMatch(r -> r.overlaps(checkIn, checkOut));
    35	        if (taken) {
    36	            throw new AppException(409, "ROOM_UNAVAILABLE", "O quarto " + roomNumber + " já está reservado nesse período.");
    37	        }
    38	        Reservation reservation = Reservation.pending(room, guestName, guestEmail, identity, checkIn, checkOut,
    39	                guests, plan, prices.calculate(room.type(), checkIn, checkOut, plan));
    40	        reservations.insert(reservation);
    41	        return reservation;
    42	    }
    43	
    44	    public Reservation get(long id) {
    45	        return reservations.find(id).orElseThrow(() ->
    46	                new AppException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe."));
    47	    }
    48	
    49	    public synchronized Reservation confirm(long id) {
    50	        Reservation r = change(id, Reservation::confirm);
    51	        messages.save(ConfirmationEmail.of(r));
    52	        return r;
    53	    }
    54	
    55	    public synchronized Reservation cancel(long id) {
    56	        return change(id, Reservation::cancel);
    57	    }
    58	
    59	    public synchronized Reservation checkIn(long id) {
    60	        return change(id, Reservation::startStay);
    61	    }
    62	
    63	    public synchronized Reservation checkOut(long id) {
    64	        return change(id, Reservation::endStay);
    65	    }
    66	
    67	    /** Segunda via: só existe para reserva paga. */
    68	    public Reservation paidReservation(long id) {
    69	        Reservation r = get(id);
    70	        if (!r.status().paid()) {
    71	            throw AppException.notAllowed("Só existe documento para reserva paga; situação atual: " + r.status() + ".");
    72	        }
    73	        return r;
    74	    }
    75	
    76	    private Reservation change(long id, Consumer<Reservation> operation) {
    77	        Reservation r = get(id);
    78	        operation.accept(r);
    79	        reservations.update(r);
    80	        return r;
    81	    }
    82	}
