     1	package br.com.marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.YearMonth;
     6	import java.util.Comparator;
     7	import java.util.List;
     8	
     9	public class ReportService {
    10	    private final ReservationRepository reservations;
    11	    private final RoomCatalog rooms;
    12	
    13	    public ReportService(ReservationRepository reservations, RoomCatalog rooms) {
    14	        this.reservations = reservations;
    15	        this.rooms = rooms;
    16	    }
    17	
    18	    public String occupancy(LocalDate night) {
    19	        List<Reservation> occupying = reservations.findAll().stream()
    20	                .filter(r -> r.status().paid())
    21	                .filter(r -> r.occupies(night))
    22	                .sorted(Comparator.comparingInt((Reservation r) -> r.room().number()).thenComparing(Reservation::id))
    23	                .toList();
    24	        StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    25	        for (Reservation r : occupying) {
    26	            csv.append(r.room().number()).append(',').append(r.room().type()).append(',').append(r.id())
    27	                    .append(',').append(r.checkIn()).append(',').append(r.checkOut()).append('\n');
    28	        }
    29	        long rooms = occupying.stream().map(r -> r.room().number()).distinct().count();
    30	        return csv.append("total,").append(rooms).append('/').append(this.rooms.count()).append('\n').toString();
    31	    }
    32	
    33	    public String revenue(YearMonth month) {
    34	        List<Reservation> kept = reservations.findAll().stream()
    35	                .filter(r -> YearMonth.from(r.checkIn()).equals(month))
    36	                .filter(r -> r.retained().signum() > 0)
    37	                .sorted(Comparator.comparing(Reservation::checkIn).thenComparing(Reservation::id))
    38	                .toList();
    39	        StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    40	        BigDecimal sum = Money.zero();
    41	        for (Reservation r : kept) {
    42	            csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn()).append(',')
    43	                    .append(r.checkOut()).append(',').append(r.status()).append(',')
    44	                    .append(r.retained().toPlainString()).append('\n');
    45	            sum = sum.add(r.retained());
    46	        }
    47	        return csv.append("total,").append(sum.toPlainString()).append('\n').toString();
    48	    }
    49	}

