     7	
     8	/** Registro dos tipos de identificação aceitos. Um tipo novo entra só na lista do construtor. */
     9	public class IdentityTypes {
    10	    private final List<IdentityType> types;
    11	
    12	    public IdentityTypes(List<IdentityType> types) {
    13	        this.types = List.copyOf(types);
    14	    }
    15	
    16	    public static IdentityTypes standard() {
    17	        return new IdentityTypes(List.of(new CpfIdentity(), new CnpjIdentity(), new PassportIdentity()));
    18	    }
    19	
    20	    /** Todos os campos de identificação que a API mostra, na ordem dos tipos. */
    21	    public List<String> allFields() {
    22	        return types.stream().flatMap(t -> t.fields().stream()).toList();
    23	    }
    24	
    25	    public IdentityType byKind(String kind) {
    26	        return types.stream().filter(t -> t.kind().equals(kind)).findFirst()
    27	                .orElseThrow(() -> new IllegalStateException("Tipo de identificação desconhecido: " + kind));
    28	    }
    29	
    30	    /** Exatamente um tipo pode aparecer no corpo, com todos os seus campos preenchidos. */
    31	    public GuestIdentity parse(Map<String, Object> body) {
    32	        List<IdentityType> used = new ArrayList<>();
    33	        for (IdentityType type : types) {
    34	            if (type.fields().stream().anyMatch(f -> body.get(f) != null)) used.add(type);
