     1	package br.com.marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.text.DecimalFormat;
     6	import java.text.DecimalFormatSymbols;
     7	import java.util.Locale;
     8	
     9	/** Dinheiro: sempre em centavos, arredondamento "meio para o par". */
    10	public final class Money {
    11	    private Money() {}
    12	
    13	    public static BigDecimal round(BigDecimal value) {
    14	        return value.setScale(2, RoundingMode.HALF_EVEN);
    15	    }
    16	
    17	    public static BigDecimal zero() {
    18	        return round(BigDecimal.ZERO);
    19	    }
    20	
    21	    /** Aplica um percentual (ex.: 15 para 15%) e arredonda para centavos. */
    22	    public static BigDecimal percentOf(BigDecimal value, int percent) {
    23	        return round(value.multiply(BigDecimal.valueOf(percent)).divide(BigDecimal.valueOf(100)));
    24	    }
    25	
    26	    /** R$ 1.234,56 */
    27	    public static String brazilian(BigDecimal value) {
    28	        return "R$ " + format(value, '.', ',');
    29	    }
    30	
    31	    /** BRL 1,234.56 */
    32	    public static String english(BigDecimal value) {
    33	        return "BRL " + format(value, ',', '.');
    34	    }
    35	
    36	    private static String format(BigDecimal value, char grouping, char decimal) {
    37	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(Locale.ROOT);
    38	        symbols.setGroupingSeparator(grouping);
    39	        symbols.setDecimalSeparator(decimal);
    40	        return new DecimalFormat("#,##0.00", symbols).format(round(value));
    41	    }
    42	}
