     1	package br.com.marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	public class PriceCalculator {
     7	    private static final int HIGH_SEASON_SURCHARGE_PERCENT = 20;
     8	
     9	    public Price calculate(RoomType type, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    10	        BigDecimal subtotal = Money.zero();
    11	        int nights = 0;
    12	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    13	            subtotal = subtotal.add(nightPrice(type, night));
    14	            nights++;
    15	        }
    16	        BigDecimal discount = Money.percentOf(subtotal, plan.discountPercent());
    17	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
    18	    }
    19	
    20	    private BigDecimal nightPrice(RoomType type, LocalDate night) {
    21	        BigDecimal rate = type.nightlyRate();
    22	        if (!isHighSeason(night)) return Money.round(rate);
    23	        return Money.percentOf(rate, 100 + HIGH_SEASON_SURCHARGE_PERCENT);
    24	    }
    25	
    26	    /** 15/12 até fim de fevereiro, e julho inteiro. */
    27	    static boolean isHighSeason(LocalDate day) {
    28	        int month = day.getMonthValue();
    29	        return month == 1 || month == 2 || month == 7 || (month == 12 && day.getDayOfMonth() >= 15);
    30	    }
    31	}
